def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Count rounds to establish basic pattern
    my_score = 0
    opp_score = 0
    c_count = 0
    d_count = 0

    for i in range(n):
        my, opp = history[i]
        if my == 'C' and opp == 'C':
            my_score += 3
            opp_score += 3
        elif my == 'C' and opp == 'D':
            my_score += 0
            opp_score += 5
        elif my == 'D' and opp == 'C':
            my_score += 5
            opp_score += 0
        else:
            my_score += 1
            opp_score += 1
        if opp == 'C':
            c_count += 1
        else:
            d_count += 1

    # Calculate opponent's defection rate
    opp_defect_rate = d_count / n if n > 0 else 0

    # If opponent is mostly cooperative, cooperate
    if opp_defect_rate < 0.2:
        # But occasionally defect to test and exploit
        if rng.random() < 0.05:
            return 'D'
        return 'C'

    # If opponent is mostly defecting, defect
    if opp_defect_rate > 0.8:
        # Occasionally cooperate to see if they change
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # Tit-for-tat style with forgiveness for moderate opponents
    if n > 0:
        last_my, last_opp = history[-1]
        # If opponent just cooperated, cooperate back
        if last_opp == 'C':
            # But check for patterns of alternating
            if n >= 4:
                recent_opp = [history[i][1] for i in range(max(0, n-4), n)]
                opp_coops = sum(1 for a in recent_opp if a == 'C')
                if opp_coops >= 3:
                    # Opponent is cooperating, be nice
                    return 'C'
                elif opp_coops <= 1:
                    # Opponent is defecting, punish
                    return 'D'
            return 'C'
        else:
            # Opponent defected last round
            # Check if this is a one-time defection or pattern
            if n >= 3:
                recent_opp = [history[i][1] for i in range(max(0, n-3), n)]
                opp_defects = sum(1 for a in recent_opp if a == 'D')
                if opp_defects >= 2:
                    # Pattern of defection, retaliate
                    return 'D'
                else:
                    # Isolated defection, forgive but be cautious
                    if rng.random() < 0.7:
                        return 'C'
                    return 'D'
            return 'D'

    return 'C'

